"""F02: generate a local forest edge texture from existing verified map art.

The render-only extension never alters RXDATA, dimensions, collisions, MapIDs,
events, connections, PBS or the save namespace.
"""
import struct
import zlib
from collections import Counter
from pathlib import Path
from audit_sinnoh_rxdata import read_marshal
from sinnoh_visual_qa import Canvas,png,tile_art
from sinnoh_private_visual import TILESET,donor_maps

ROOT=Path(__file__).resolve().parents[2]
TEXTURE="Graphics/Tilesets/SNQA_ForestEdge.png"
SIZE=64

def atlas_pixels(raw):
    # The compact atlas is generated by sinnoh_visual_qa.png (RGBA, filter 0).
    w,h=struct.unpack_from(">II",raw,16)
    if w!=256 or not 32<=h<=4096 or h%32 or raw[24:29]!=bytes((8,6,0,0,0)):
        raise ValueError("F02_ATLAS_FORMAT")
    off=8;parts=[]
    while off+12<=len(raw):
        n=struct.unpack_from(">I",raw,off)[0]
        if off+12+n>len(raw):raise ValueError("F02_ATLAS_CHUNK")
        kind=raw[off+4:off+8]
        if kind==b"IDAT":parts.append(raw[off+8:off+8+n])
        off+=12+n
        if kind==b"IEND":break
    stride=w*4
    data=zlib.decompress(b"".join(parts))
    if len(data)!=(stride+1)*h or any(data[y*(stride+1)]!=0 for y in range(h)):
        raise ValueError("F02_ATLAS_SCANLINES")
    return w,h,b"".join(data[y*(stride+1)+1:(y+1)*(stride+1)] for y in range(h))

def tree_texture(blobs,mapping):
    """Prefer repeated, opaque green blocked edge scenery from the local donor.
    An authored tree fallback is used when a suitable donor patch is absent.
    No donor source images or resulting texture are stored in the repository.
    """
    w,h,pixels=atlas_pixels(blobs["Graphics/Tilesets/"+TILESET+".png"])
    tiles=read_marshal(blobs["Data/Tilesets.rxdata"],"F02_TILESETS")
    cache={}
    def compose(stack):
        if stack in cache:return cache[stack]
        out=bytearray(32*32*4)
        for i in stack:
            idx=i-384
            if not 0<=idx<w*h//1024:
                cache[stack]=None;return None
            ox=(idx%8)*32;oy=(idx//8)*32
            for y in range(32):
                for x in range(32):
                    pos=(y*32+x)*4;src=((oy+y)*w+ox+x)*4
                    r,g,b,a=pixels[src:src+4]
                    if a==255:out[pos:pos+4]=bytes((r,g,b,255))
                    elif a and out[pos+3]==255:
                        out[pos:pos+4]=bytes(((r*a+out[pos]*(255-a))//255,
                            (g*a+out[pos+1]*(255-a))//255,
                            (b*a+out[pos+2]*(255-a))//255,255))
                    elif a:
                        # Partial-alpha first layer is not a fully opaque sample.
                        cache[stack]=None;return None
        if any(out[i]!=255 for i in range(3,len(out),4)):
            cache[stack]=None;return None
        green=sum(1 for r,g,b in zip(out[0::4],out[1::4],out[2::4])
                  if g>=r+8 and g>=b+10 and g>=38)
        dark=sum(1 for r,g,b in zip(out[0::4],out[1::4],out[2::4])
                 if g>=r and g>=b and 38<=g<=145)
        cache[stack]=(bytes(out),green,dark)
        return cache[stack]
    counts=Counter();locations={}
    for sym in donor_maps(mapping):
        mid=mapping[sym]
        m=read_marshal(blobs["Data/Map%03d.rxdata"%mid],"F02_MAP").attrs
        mw,mh=m["@width"],m["@height"];n=mw*mh
        a=tiles[m["@tileset_id"]].attrs
        p=struct.unpack_from("<%dH"%((len(a["@passages"].data)-20)//2),a["@passages"].data,20)
        t=struct.unpack_from("<%dH"%((len(a["@terrain_tags"].data)-20)//2),a["@terrain_tags"].data,20)
        cells=struct.unpack_from("<%dH"%(n*3),m["@data"].data,20)
        candidates={}
        for y in range(mh):
            for x in range(mw):
                if min(x,y,mw-1-x,mh-1-y)>5:continue
                stack=tuple(cells[z*n+y*mw+x] for z in range(3) if cells[z*n+y*mw+x])
                if not stack or not all(i<len(p) and i<len(t) and t[i]==0 for i in stack):continue
                if not any(p[i]&15==15 for i in stack):continue
                sample=compose(stack)
                if sample and sample[1]>=350 and sample[2]>=100:candidates[x,y]=stack
        for y in range(mh-1):
            for x in range(mw-1):
                coords=((x,y),(x+1,y),(x,y+1),(x+1,y+1))
                if not all(q in candidates for q in coords):continue
                key=tuple(candidates[q] for q in coords)
                # Require more than a single monotonous ground tile.
                if len(set(key))<2:continue
                counts[key]+=1;locations.setdefault(key,(sym,x,y))
    if counts:
        key=max(counts,key=lambda k:(counts[k],sum(cache[s][1]+cache[s][2] for s in k),k))
        if counts[key]>=2:
            texture=bytearray(SIZE*SIZE*4)
            for j,stack in enumerate(key):
                image=cache[stack][0]
                for y in range(32):
                    pos=((j//2*32+y)*SIZE+j%2*32)*4
                    texture[pos:pos+128]=image[y*128:(y+1)*128]
            sym,x,y=locations[key]
            return png(SIZE,SIZE,bytes(texture)),{"art":"local_repeated_green_blocked_donor_patch",
                "sample_symbol":sym,"sample_xy":[x,y],"repetitions":counts[key]}
    # Authorial fallback: grass beneath four complete tree crowns.
    c=Canvas(SIZE,SIZE)
    for j in range(4):
        ground=tile_art(35+j%3,True)
        tree=tile_art(46+j%2,True)
        for i in range(0,len(ground.raw),4):
            if tree.raw[i+3]:ground.raw[i:i+4]=tree.raw[i:i+4]
        c.paste2(ground,j%2*32,j//2*32)
    return png(SIZE,SIZE,bytes(c.raw)),{"art":"original_tree_fallback"}

def build(blobs,mapping,root=ROOT):
    ids=sorted(mapping[sym] for sym in donor_maps(mapping))
    if len(ids)!=len(set(ids)) or not ids:raise ValueError("F02_MAP_IDS")
    texture,report=tree_texture(blobs,mapping)
    script=(root/"scripts/regions/SinnohForestEdge.rb").read_text("utf-8")
    if script.count("__F02_MAP_IDS__")!=1:raise ValueError("F02_TEMPLATE")
    code=script.replace("__F02_MAP_IDS__",str(ids)).encode("utf-8")
    return texture,code,{**report,"map_ids":ids,"mode":"render_only_void_tiles",
        "geometry_changed":False,"native_visual_verified":False}
